import numpy as np
X = np.array([[0., 0., 0.], [1., .1, 0.], [.2, 1.2, .1], [.1, .2, 1.1], [1.1, 1., 1.3]])
T = np.array([[0, 1, 2, 3], [1, 2, 3, 4]])
T[0, 1] = 0
def _invalid_status(function):
    try:
        function(X, T)
    except ValueError:
        return 1.0
    except Exception:
        return 2.0
    return 0.0
assert np.allclose(_invalid_status(reference_geometry), target)

